/* ============================================================================
 * 界面语言（i18n）
 * ============================================================================
 *
 * 做法：给需要翻译的元素加 `data-i18n="key"`，由 applyI18n() 统一替换文本；
 * 占位符用 `data-i18n-ph`，提示用 `data-i18n-title`。
 *
 * 为什么是「按 key 查表」而不是「按中文原文查表」：
 *   按原文查表在改动文案时容易漏改——改了中文却忘了改表，
 *   英文界面就会残留旧文案。按 key 则一眼能看出哪个没翻译。
 *
 * 动态拼接的文本（例如「显示 94 个 · 其中 76 个将加载」）走 t() 函数，
 * 支持 {n} 这种占位符替换。
 */
